  1	import { readFile, readdir } from 'fs/promises';
  2	import { join } from 'path';
  3	import type { Dirent } from 'fs';
  4	import {
  5	  KnowledgeStoreSchema,
  6	  InsightSchema,
  7	  PROJECT_SLUG_REGEX,
  8	  type KnowledgeStore,
  9	  type Insight,
 10	  type InsightScope,
 11	} from '../schema/knowledge.js';
 12	import { atomicWriteJson } from './atomic-writer.js';
 13	import { withLock } from './file-lock.js';
 14	import { now } from '../utils/timestamp.js';
 15	
 16	/**
 17	 * Manages the `.knowledge/` directory, providing all CRUD operations for
 18	 * insights with atomic writes, file locking, and in-memory search/filter logic.
 19	 *
 20	 * Storage layout (relative to `ledgerRoot`):
 21	 *   .knowledge/
 22	 *     .lock                     — lock file created by withLock
 23	 *     global-insights.json      — insights with scope: 'global'
 24	 *     {slug}-insights.json      — insights scoped to a specific project
 25	 *
 26	 * Locking strategy:
 27	 *   - All read-modify-write sequences (addInsight, updateInsight, deleteInsight)
 28	 *     acquire a single lock on knowledgeDir() for the entire operation.
 29	 *   - All writes use atomicWriteJson() — write-to-temp-then-rename.
 30	 *   - Pure reads (readGlobalStore, readProjectStore, searchInsights, listInsights)
 31	 *     do not acquire a lock, consistent with the LedgerStore pattern.
 32	 *
 33	 * scope === 'project' + project_slug constraint:
 34	 *   The Zod schema accepts project_slug as optional to remain context-free.
 35	 *   This class enforces the constraint: addInsight() throws if scope is 'project'
 36	 *   and project_slug is absent.
 37	 */
 38	export class KnowledgeStoreManager {
 39	  public readonly ledgerRoot: string;
 40	
 41	  constructor(ledgerRoot: string) {
 42	    this.ledgerRoot = ledgerRoot;
 43	  }
 44	
 45	  // ==================== Path Helpers ====================
 46	
 47	  knowledgeDir(): string {
 48	    return join(this.ledgerRoot, '.knowledge');
 49	  }
 50	
 51	  globalStorePath(): string {
 52	    return join(this.knowledgeDir(), 'global-insights.json');
 53	  }
 54	
 55	  projectStorePath(slug: string): string {
 56	    this._validateSlug(slug);
 57	    return join(this.knowledgeDir(), `${slug}-insights.json`);
 58	  }
 59	
 60	  // ==================== Read Methods ====================
 61	
 62	  /**
 63	   * Reads and validates the global insights store.
 64	   * Returns a valid empty KnowledgeStore if the file does not yet exist.
 65	   *
 66	   * @throws Error if the file exists but contains malformed JSON or fails schema validation
 67	   */
 68	  async readGlobalStore(): Promise<KnowledgeStore> {
 69	    return this._readStore(this.globalStorePath());
 70	  }
 71	
 72	  /**
 73	   * Reads and validates a project-scoped insights store.
 74	   * Returns a valid empty KnowledgeStore if the file does not yet exist.
 75	   *
 76	   * @param slug - Project slug (used to derive the filename)
 77	   * @throws Error if the file exists but contains malformed JSON or fails schema validation
 78	   */
 79	  async readProjectStore(slug: string): Promise<KnowledgeStore> {
 80	    return this._readStore(this.projectStorePath(slug));
 81	  }
 82	
 83	  // ==================== Write Methods ====================
 84	
 85	  /**
 86	   * Writes the global insights store atomically under a lock.
 87	   * Validates the data against KnowledgeStoreSchema before writing.
 88	   *
 89	   * @param data - Store data to persist
 90	   * @throws Error if validation fails or write fails
 91	   * @warning Do NOT call this method from inside a withLock(knowledgeDir, ...) callback.
 92	   *   The CRUD methods (addInsight, updateInsight, deleteInsight) intentionally bypass
 93	   *   this method and call atomicWriteJson directly to avoid nested lock acquisition,
 94	   *   which would deadlock. This method is safe only at the top level.
 95	   */
 96	  async writeGlobalStore(data: KnowledgeStore): Promise<void> {
 97	    await withLock(this.knowledgeDir(), async () => {
 98	      const validated = KnowledgeStoreSchema.parse(data);
 99	      await atomicWriteJson(this.globalStorePath(), validated);
100	    });

101	 * @throws ApiError VALIDATION_ERROR for any rejected value.
102	 */
103	export function parseKnowledgeId(raw: string): number {
104	  // Reject strings containing a decimal point before numeric coercion —
105	  // this catches "1.5" and also "2.0", both of which the caller must treat
106	  // as non-integer IDs even though Number("2.0") === 2.
107	  if (raw.includes('.')) {
108	    throw new ApiError('VALIDATION_ERROR', 'Invalid insight id.');
109	  }
110	  const n = Number(raw);
111	  if (!Number.isInteger(n) || n <= 0) {
112	    throw new ApiError('VALIDATION_ERROR', 'Invalid insight id.');
113	  }
114	  return n;
115	}
116	
117	// ---------------------------------------------------------------------------
118	// Interface definitions
119	// ---------------------------------------------------------------------------
120	
121	/** Raw query parameters accepted by GET /api/knowledge. */
122	export interface KnowledgeListParams {
123	  scope?: string;
124	  category?: string;
125	  /** Comma-separated list of tags to filter by. */
126	  tags?: string;
127	  project_slug?: string;
128	  /** Full-text search query — delegates to searchInsights when present. */
129	  query?: string;
130	  limit?: number | string;
131	  offset?: number | string;
132	}
133	
134	// ---------------------------------------------------------------------------
135	// GET /api/knowledge
136	// ---------------------------------------------------------------------------
137	
138	/**
139	 * Lists (or searches) knowledge insights stored in the ledger's `.knowledge/` directory.
140	 *
141	 * - When `query` is present, delegates to `KnowledgeStoreManager.searchInsights()`.
142	 * - Otherwise calls `KnowledgeStoreManager.listInsights()` with scope/category/tags filters.
143	 * - `scope` is validated via `InsightScope.safeParse()`; unrecognised values are silently
144	 *   treated as "no scope filter" rather than causing an error.
145	 * - `tags` is a comma-separated string that is split before being forwarded.
146	 * - `limit` and `offset` are coerced to non-negative integers; invalid/missing values
147	 *   are silently ignored (limit → undefined, offset → 0).
148	 */
149	export async function handleListKnowledge(
150	  ledgerRoot: string,
151	  params: KnowledgeListParams = {}
152	): Promise<Insight[]> {
153	  const manager = new KnowledgeStoreManager(ledgerRoot);
154	
155	  // Validate scope — unrecognised values fall back to undefined (no filter).
156	  const scopeResult = InsightScope.safeParse(params.scope);
157	  const scope = scopeResult.success ? scopeResult.data : undefined;
158	
159	  const category = params.category ?? undefined;
160	  const project_slug = params.project_slug ?? undefined;
161	
162	  // Split comma-separated tags; ignore empty segments.
163	  const tags =
164	    params.tags && params.tags.trim().length > 0
165	      ? params.tags
166	          .split(',')
167	          .map((t) => t.trim())
168	          .filter((t) => t.length > 0)
169	      : undefined;
170	
171	  // Coerce pagination params.
172	  const limitRaw = params.limit !== undefined ? Math.floor(Number(params.limit)) : NaN;
173	  const limit = !isNaN(limitRaw) && limitRaw > 0 ? limitRaw : undefined;
174	
175	  const offsetRaw = params.offset !== undefined ? Math.floor(Number(params.offset)) : NaN;
176	  const offset = !isNaN(offsetRaw) && offsetRaw >= 0 ? offsetRaw : 0;
177	
178	  if (params.query && params.query.trim().length > 0) {
179	    return manager.searchInsights(params.query.trim(), { scope, project_slug, category, tags, limit, offset });
180	  }
181	
182	  return manager.listInsights({ scope, category, tags, project_slug, limit, offset });
183	}
184	
185	// ---------------------------------------------------------------------------
186	// PATCH /api/knowledge/:id
187	// ---------------------------------------------------------------------------
188	
189	/**
190	 * Updates an existing knowledge insight identified by its numeric ID.
191	 *
192	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
193	 * for non-integer, zero, or floating-point strings). Validates the request body
194	 * via `KnowledgeUpdateBodySchema` (throws VALIDATION_ERROR for unknown fields or
195	 * type mismatches). Extracts `scope` and `project_slug` discriminator fields to
196	 * scope the update to the correct store.
197	 *
198	 * `superseded_by: null` in the body is mapped to `undefined` so the field is
199	 * cleared (removed) on the stored insight.
200	 *
201	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
202	 *
203	 * @param ledgerRoot  Absolute path to the central ledger root.
204	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
205	 * @param body        Parsed request body (any shape — validated here).
206	 * @returns The updated Insight.
207	 */
208	export async function handleUpdateKnowledge(
209	  ledgerRoot: string,
210	  rawId: string,
211	  body: unknown
212	): Promise<Insight> {
213	  const id = parseKnowledgeId(rawId);
214	
215	  const parseResult = KnowledgeUpdateBodySchema.safeParse(body);
216	  if (!parseResult.success) {
217	    validationError('Invalid knowledge update body.', parseResult.error.issues);
218	  }
219	
220	  const { scope, project_slug, superseded_by, ...rest } = parseResult.data;
221	
222	  // Map superseded_by: null → undefined so the field is cleared on the stored insight.
223	  const updates: Parameters<KnowledgeStoreManager['updateInsight']>[1] = {
224	    ...rest,
225	    ...(superseded_by === null ? { superseded_by: undefined } : superseded_by !== undefined ? { superseded_by } : {}),
226	  };
227	
228	  const manager = new KnowledgeStoreManager(ledgerRoot);
229	
230	  try {
231	    return await manager.updateInsight(id, updates, { scope, project_slug });
232	  } catch (err) {
233	    const msg = err instanceof Error ? err.message : String(err);
234	    if (msg.includes('not found')) {
235	      throw new ApiError('NOT_FOUND', 'Insight not found.');
236	    }
237	    throw err;
238	  }
239	}
240	
241	// ---------------------------------------------------------------------------
242	// DELETE /api/knowledge/:id
243	// ---------------------------------------------------------------------------
244	
245	/**
246	 * Deletes an existing knowledge insight identified by its numeric ID.
247	 *
248	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
249	 * for non-integer, zero, or floating-point strings). Requires `scope` as a
250	 * query parameter; when `scope === 'project'`, `project_slug` is also required
251	 * (throws VALIDATION_ERROR if absent). Scopes the deletion to the correct store
252	 * to prevent accidental cross-scope deletion when the same numeric ID exists in
253	 * multiple stores.
254	 *
255	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
256	 *
257	 * @param ledgerRoot   Absolute path to the central ledger root.
258	 * @param rawId        Raw ID string from the URL parameter (e.g. "42").
259	 * @param scope        Required scope query parameter ('global' or 'project').
260	 * @param project_slug Required when scope is 'project'; the project slug.
261	 * @returns `null` — consistent with other delete handlers.
262	 */
263	export async function handleDeleteKnowledge(
264	  ledgerRoot: string,
265	  rawId: string,
266	  scope: string | undefined,
267	  project_slug?: string
268	): Promise<null> {
269	  const id = parseKnowledgeId(rawId);
270	
271	  // Validate scope — required and must be a recognised InsightScope value.
272	  const scopeResult = InsightScope.safeParse(scope);
273	  if (!scopeResult.success) {
274	    validationError('scope query parameter is required and must be "global" or "project".');
275	  }
276	  const validatedScope = scopeResult.data;
277	
278	  // project_slug is required when scope === 'project'.
279	  if (validatedScope === 'project' && !project_slug) {
280	    validationError('project_slug query parameter is required when scope is "project".');
281	  }
282	
283	  const manager = new KnowledgeStoreManager(ledgerRoot);
284	
285	  try {
286	    await manager.deleteInsight(id, { scope: validatedScope, project_slug });
287	  } catch (err) {
288	    const msg = err instanceof Error ? err.message : String(err);
289	    if (msg.includes('not found')) {
290	      throw new ApiError('NOT_FOUND', 'Insight not found.');
291	    }
292	    throw err;
293	  }
294	
295	  return null;
296	}
297	
298	// ---------------------------------------------------------------------------
299	// POST /api/knowledge/:id/promote
300	// ---------------------------------------------------------------------------

101	  }
102	
103	  /**
104	   * Writes a project-scoped insights store atomically under a lock.
105	   * Validates the data against KnowledgeStoreSchema before writing.
106	   *
107	   * @param slug - Project slug
108	   * @param data - Store data to persist
109	   * @throws Error if validation fails or write fails
110	   * @warning Do NOT call this method from inside a withLock(knowledgeDir, ...) callback.
111	   *   The CRUD methods (addInsight, updateInsight, deleteInsight) intentionally bypass
112	   *   this method and call atomicWriteJson directly to avoid nested lock acquisition,
113	   *   which would deadlock. This method is safe only at the top level.
114	   */
115	  async writeProjectStore(slug: string, data: KnowledgeStore): Promise<void> {
116	    await withLock(this.knowledgeDir(), async () => {
117	      const validated = KnowledgeStoreSchema.parse(data);
118	      await atomicWriteJson(this.projectStorePath(slug), validated);
119	    });
120	  }
121	
122	  // ==================== ID Generation ====================
123	
124	  /**
125	   * Increments the store's next_id counter and returns the formatted ID string.
126	   *
127	   * Mutates the store object in-place — the updated store must be written to disk
128	   * for the counter to persist across process restarts.
129	   *
130	   * @param store - The store whose counter should be incremented
131	   * @returns Formatted ID string in KN-NNNN format (e.g., "KN-0001" for next_id=1)
132	   */
133	  nextId(store: KnowledgeStore): string {
134	    const id = store.next_id;
135	    store.next_id = id + 1;
136	    return `KN-${String(id).padStart(4, '0')}`;
137	  }
138	
139	  // ==================== CRUD Operations ====================
140	
141	  /**
142	   * Adds a new insight to the appropriate store (global or project-scoped).
143	   *
144	   * Assigns the numeric id from the store's next_id counter and persists the
145	   * incremented counter. Enforces the project_slug requirement for project-scoped
146	   * insights. The entire read-modify-write sequence runs under a single lock.
147	   *
148	   * @param input - Insight data without the id field (auto-assigned from next_id)
149	   * @returns The created Insight with the assigned numeric id
150	   * @throws Error if scope === 'project' and project_slug is absent
151	   */
152	  async addInsight(input: Omit<Insight, 'id'>): Promise<Insight> {
153	    if (input.scope === 'project' && !input.project_slug) {
154	      throw new Error('project_slug is required for project-scoped insights');
155	    }
156	
157	    return await withLock(this.knowledgeDir(), async () => {
158	      const storePath =
159	        input.scope === 'global'
160	          ? this.globalStorePath()
161	          : this.projectStorePath(input.project_slug!);
162	
163	      const store = await this._readStore(storePath);
164	
165	      // Save the numeric id before nextId increments the counter.
166	      // The KN-NNNN return value of nextId() is intentionally discarded here —
167	      // display-format IDs are produced by MCP tool layer consumers, not stored.
168	      const numericId = store.next_id;
169	      this.nextId(store);
170	
171	      const insight: Insight = InsightSchema.parse({ ...input, id: numericId });
172	      store.insights.push(insight);
173	      store.last_updated = now();
174	
175	      const validated = KnowledgeStoreSchema.parse(store);
176	      await atomicWriteJson(storePath, validated);
177	
178	      return insight;
179	    });
180	  }
181	
182	  /**
183	   * Searches insights across all (or filtered) stores for the query string.
184	   *
185	   * Applies a case-insensitive substring match against title, content, and every
186	   * entry in the tags array. Optionally narrows by tags (intersection), then
187	   * applies offset/limit pagination — in that order.
188	   *
189	   * @param query - Substring to search for
190	   * @param filters - Optional scope/category/project_slug filters to narrow the stores searched,
191	   *   plus optional tags (intersection filter), limit, and offset for pagination
192	   * @returns Insights matching the query, filtered by tags, and paginated
193	   */
194	  async searchInsights(
195	    query: string,
196	    filters?: {
197	      scope?: InsightScope;
198	      project_slug?: string;
199	      category?: string;
200	      tags?: string[];
201	      limit?: number;
202	      offset?: number;
203	    }
204	  ): Promise<Insight[]> {
205	    const { tags: tagFilter, limit, offset = 0, ...loadFilters } = filters ?? {};
206	
207	    const allInsights = await this._loadInsights(loadFilters);
208	    const q = query.toLowerCase();
209	
210	    let results = allInsights.filter(
211	      (insight) =>
212	        insight.title.toLowerCase().includes(q) ||
213	        insight.content.toLowerCase().includes(q) ||
214	        insight.tags.some((tag) => tag.toLowerCase().includes(q))
215	    );
216	
217	    if (tagFilter && tagFilter.length > 0) {
218	      results = results.filter((insight) =>
219	        tagFilter.every((tag) => insight.tags.includes(tag))
220	      );
221	    }
222	
223	    return results.slice(offset, limit !== undefined ? offset + limit : undefined);
224	  }
225	
226	  /**
227	   * Lists insights with optional scope/category/tags/project_slug filters and pagination.
228	   *
229	   * Filters are applied in this order: store selection (scope/project_slug) → category →
230	   * tags → offset → limit.
231	   *
232	   * @param filters - Scope, category, tags, project_slug filters; limit and offset for pagination
233	   * @returns Filtered and paginated insight array
234	   */
235	  async listInsights(filters: {
236	    scope?: InsightScope;
237	    category?: string;
238	    tags?: string[];
239	    project_slug?: string;
240	    limit?: number;
241	    offset?: number;
242	  }): Promise<Insight[]> {
243	    const { limit, offset = 0, tags: tagFilter, ...loadFilters } = filters;
244	
245	    let insights = await this._loadInsights(loadFilters);
246	
247	    if (tagFilter && tagFilter.length > 0) {
248	      insights = insights.filter((insight) =>
249	        tagFilter.every((tag) => insight.tags.includes(tag))
250	      );
251	    }
252	
253	    return insights.slice(offset, limit !== undefined ? offset + limit : undefined);
254	  }
255	
256	  /**
257	   * Updates an existing insight by numeric ID.
258	   *
259	   * When `filter.scope` and/or `filter.project_slug` are provided the search is
260	   * restricted to the matching store(s), preventing accidental global-insight
261	   * mutation when the same numeric ID exists in multiple stores. Without a
262	   * filter, all stores are scanned (original behaviour — preserved for
263	   * backwards compatibility).
264	   *
265	   * Applies the provided partial updates and sets updated_at to the current
266	   * timestamp. The entire read-modify-write sequence runs under a single lock.
267	   *
268	   * Immutable fields (id, scope, project_slug, created_at) are not accepted
269	   * in the updates parameter.
270	   *
271	   * @param id - Numeric insight id
272	   * @param updates - Partial insight fields to update
273	   * @param filter - Optional scope/project_slug filter to restrict which store is searched
274	   * @returns The updated Insight
275	   * @throws Error if no insight with the given id exists in the filtered stores
276	   */
277	  async updateInsight(
278	    id: number,
279	    updates: Partial<
280	      Pick<Insight, 'title' | 'content' | 'category' | 'tags' | 'source' | 'confidence' | 'superseded_by'>
281	    >,
282	    filter?: { scope?: InsightScope; project_slug?: string }
283	  ): Promise<Insight> {
284	    return await withLock(this.knowledgeDir(), async () => {
285	      const storePaths = await this._storePathsForFilter(filter);
286	
287	      for (const storePath of storePaths) {
288	        const store = await this._readStore(storePath);
289	        const idx = store.insights.findIndex((i) => i.id === id);
290	
291	        if (idx === -1) continue;
292	
293	        const updatedInsight: Insight = InsightSchema.parse({
294	          ...store.insights[idx],
295	          ...updates,
296	          updated_at: now(),
297	        });
298	
299	        store.insights[idx] = updatedInsight;
300	        store.last_updated = now();

  1	/**
  2	 * Tests for WP-001: Knowledge Handler Foundations
  3	 *
  4	 * Covers:
  5	 * - handleListKnowledge (AC-1 through AC-7)
  6	 * - parseKnowledgeId    (AC-8)
  7	 * - findInsightById     (AC-9)
  8	 *
  9	 * Uses real temp directories and KnowledgeStoreManager to seed fixture data.
 10	 */
