 17	import {
 18	  handleListKnowledge,
 19	  handleUpdateKnowledge,
 20	  handleDeleteKnowledge,
 21	  handlePromoteKnowledge,
 22	  handleMoveKnowledge,
 23	  ApiError,
 24	} from '../../gui/api-knowledge.js';
 25	import { KnowledgeStoreManager } from '../../src/storage/knowledge-store.js';
